use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut keys: Vec<int> = []
    let mut left: Vec<int> = []
    let mut right: Vec<int> = []
    let mut root: int = -1
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 { continue }
        let cmd = parts[0]
        let mut x: int = 0
        if parts.len() > 1 { x = parts[1].parse::<int>().unwrap_or(0) }
        if cmd == "insert" || cmd == "contains" || cmd == "delete" {
            let mut cur = root
            let mut par: int = -1
            let mut dir = 0
            while cur != -1 && keys[cur as usize] != x {
                par = cur
                if x < keys[cur as usize] {
                    dir = 0
                    cur = left[cur as usize]
                } else {
                    dir = 1
                    cur = right[cur as usize]
                }
            }
            if cmd == "contains" {
                if cur != -1 { println("yes") } else { println("no") }
            } else if cmd == "insert" {
                if cur != -1 {
                    println("dup")
                } else {
                    let id: int = keys.len() as int
                    keys.push(x)
                    left.push(-1)
                    right.push(-1)
                    if par == -1 {
                        root = id
                    } else if dir == 0 {
                        left[par as usize] = id
                    } else {
                        right[par as usize] = id
                    }
                    println("ok")
                }
            } else {
                if cur == -1 {
                    println("missing")
                } else {
                    let l = left[cur as usize]
                    let r = right[cur as usize]
                    if l != -1 && r != -1 {
                        let mut sp = cur
                        let mut s = r
                        while left[s as usize] != -1 {
                            sp = s
                            s = left[s as usize]
                        }
                        keys[cur as usize] = keys[s as usize]
                        if sp == cur {
                            right[cur as usize] = right[s as usize]
                        } else {
                            left[sp as usize] = right[s as usize]
                        }
                    } else {
                        let mut child = l
                        if l == -1 { child = r }
                        if par == -1 {
                            root = child
                        } else if dir == 0 {
                            left[par as usize] = child
                        } else {
                            right[par as usize] = child
                        }
                    }
                    println("ok")
                }
            }
        } else if cmd == "inorder" {
            if root == -1 {
                println("<empty>")
            } else {
                let mut out: Vec<string> = []
                let mut stack: Vec<int> = []
                let mut cur = root
                while cur != -1 || stack.len() > 0 {
                    while cur != -1 {
                        stack.push(cur)
                        cur = left[cur as usize]
                    }
                    let n = stack.pop().unwrap_or(0)
                    out.push("${keys[n as usize]}")
                    cur = right[n as usize]
                }
                println(out.join(" "))
            }
        } else if cmd == "height" {
            let mut h = 0
            let mut level: Vec<int> = []
            if root != -1 { level.push(root) }
            while level.len() > 0 {
                h += 1
                let mut next: Vec<int> = []
                for n in level {
                    if left[n as usize] != -1 { next.push(left[n as usize]) }
                    if right[n as usize] != -1 { next.push(right[n as usize]) }
                }
                level = next
            }
            println("${h}")
        } else if cmd == "min" || cmd == "max" {
            if root == -1 {
                println("empty")
            } else {
                let mut cur = root
                if cmd == "min" {
                    while left[cur as usize] != -1 { cur = left[cur as usize] }
                } else {
                    while right[cur as usize] != -1 { cur = right[cur as usize] }
                }
                println("${keys[cur as usize]}")
            }
        }
    }
}

